package repocheck

import (
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"testing"

	"github.com/azrtydxb/momo/gen"
)

const spdxTag = "SPDX-License-Identifier: Apache-2.0"

// goGenerated is the Go convention for generated files, which carry the
// generator's own header.
var goGenerated = regexp.MustCompile(`(?m)^// Code generated .* DO NOT EDIT\.$`)

// generatedPrefixes are the only directories whose files may carry the Go
// generated-file marker instead of the SPDX header: the Ent client of the
// importer fixture, generated by Ent. Everywhere else the header is required.
var generatedPrefixes = []string{"internal/compat/entfixture/ent/"}

// gqlgenGenerated are the files of the GraphQL example that gqlgen writes: they
// carry gqlgen's own generated-file marker instead of the SPDX header.
var gqlgenGenerated = []string{
	"internal/integration/graphql/example/graph/generated/exec.go",
	"internal/integration/graphql/example/graph/model/models_gen.go",
}

// gqlgenRewritten is the one file gqlgen rewrites without a marker: it keeps the
// resolver bodies and drops the leading comment, so no SPDX header can stay.
// resolver.go, which gqlgen never rewrites, keeps its header and is not here.
const gqlgenRewritten = "internal/integration/graphql/example/graph/schema.resolvers.go"

// handwrittenPrefixes are inside generatedPrefixes but hand-written (the Ent
// schema the importer reads), so they need the SPDX header.
var handwrittenPrefixes = []string{"internal/compat/entfixture/ent/schema/"}

// hasLicenseHeader reports whether the file at the slash-separated path rel
// (relative to the repository root) starts with an acceptable header.
func hasLicenseHeader(rel, head string) bool {
	if strings.Contains(head, spdxTag) {
		return true
	}
	if rel == gqlgenRewritten {
		return true
	}
	if slices.Contains(gqlgenGenerated, rel) && goGenerated.MatchString(head) {
		return true
	}
	for _, p := range handwrittenPrefixes {
		if strings.HasPrefix(rel, p) {
			return false
		}
	}
	for _, p := range generatedPrefixes {
		if strings.HasPrefix(rel, p) && goGenerated.MatchString(head) {
			return true
		}
	}
	return false
}

func TestGeneratedMarkerIsScoped(t *testing.T) {
	marker := "// Code generated by ent, DO NOT EDIT.\n\npackage ent\n"
	if !hasLicenseHeader("internal/compat/entfixture/ent/client.go", marker) {
		t.Error("the generated Ent client needs no SPDX header")
	}
	if hasLicenseHeader("internal/other/file.go", marker) || hasLicenseHeader("importer/ent/read.go", marker) {
		t.Error("the generated-file marker must not exempt files outside the Ent client")
	}
	if hasLicenseHeader("internal/compat/entfixture/ent/schema/user.go", marker) {
		t.Error("the hand-written Ent schema needs the SPDX header even next to the generated client")
	}
	if !hasLicenseHeader("internal/compat/entfixture/ent/schema/user.go", "// "+spdxTag+"\n") {
		t.Error("the Ent schema with an SPDX header is accepted")
	}
	if !hasLicenseHeader("importer/ent/read.go", "// "+spdxTag+"\n") {
		t.Error("the SPDX header is accepted everywhere")
	}
}

// Catches: the gqlgen exemption growing to the whole example directory, so a
// handwritten file there (the resolver) or a file without gqlgen's marker passes
// without a licence header.
func TestGqlgenExemptionIsScoped(t *testing.T) {
	dir := "internal/integration/graphql/example/graph/"
	marker := "// Code generated by github.com/99designs/gqlgen, DO NOT EDIT.\n\npackage generated\n"
	if !hasLicenseHeader(dir+"generated/exec.go", marker) || !hasLicenseHeader(dir+"model/models_gen.go", marker) {
		t.Error("gqlgen's generated files need no SPDX header")
	}
	if hasLicenseHeader(dir+"generated/exec.go", "package generated\n") {
		t.Error("a gqlgen file without gqlgen's marker needs the SPDX header")
	}
	if hasLicenseHeader(dir+"resolver.go", "package graph\n") || hasLicenseHeader(dir+"resolver.go", marker) {
		t.Error("the scaffolded root resolver needs its SPDX header")
	}
	if hasLicenseHeader(dir+"other.go", marker) || hasLicenseHeader("internal/integration/graphql/other.go", marker) {
		t.Error("the marker must not exempt other files of the example")
	}
	if !hasLicenseHeader(dir+"schema.resolvers.go", "package graph\n") {
		t.Error("gqlgen rewrites schema.resolvers.go without a header")
	}
	if hasLicenseHeader("internal/integration/openapi/example/handlers/other.go", "package handlers\n") {
		t.Error("the exemption must not reach other examples")
	}
}

// TestDependabotCoversFixtureModules fails when a nested Go module (any go.mod
// below the root, outside testdata and tool directories) is missing from
// dependabot.yml: its dependencies would never be updated.
func TestDependabotCoversFixtureModules(t *testing.T) {
	root := repoRoot(t)
	b, err := os.ReadFile(filepath.Join(root, ".github", "dependabot.yml"))
	if err != nil {
		t.Fatal(err)
	}
	var mods []string
	err = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			case ".git", ".claude", "testdata", "node_modules", "vendor":
				return filepath.SkipDir
			}
			return nil
		}
		if d.Name() == "go.mod" && filepath.Dir(p) != root {
			mods = append(mods, filepath.Dir(p))
		}
		return nil
	})
	if err != nil || len(mods) == 0 {
		t.Fatalf("no nested modules found: %v", err)
	}
	for _, m := range mods {
		rel, err := filepath.Rel(root, m)
		if err != nil {
			t.Fatal(err)
		}
		dir := "/" + filepath.ToSlash(rel)
		if !strings.Contains(string(b), "directory: "+dir+"\n") {
			t.Errorf("dependabot.yml does not list %s", dir)
		}
	}
}

func repoRoot(t *testing.T) string {
	t.Helper()
	wd, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	return filepath.Join(wd, "..", "..")
}

func TestRepoFiles(t *testing.T) {
	root := repoRoot(t)
	for _, p := range []string{
		"LICENSE", "SECURITY.md", "CONTRIBUTING.md", "CODE_OF_CONDUCT.md",
		".github/ISSUE_TEMPLATE/bug_report.yml",
		".github/ISSUE_TEMPLATE/feature_request.yml",
		".github/ISSUE_TEMPLATE/config.yml",
		".github/PULL_REQUEST_TEMPLATE.md",
	} {
		if _, err := os.Stat(filepath.Join(root, p)); err != nil {
			t.Errorf("missing %s: %v", p, err)
		}
	}
	lic, err := os.ReadFile(filepath.Join(root, "LICENSE"))
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(lic), "Apache License") || !strings.Contains(string(lic), "Version 2.0, January 2004") {
		t.Error("LICENSE is not the Apache-2.0 text")
	}
	err = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			switch d.Name() {
			// .claude holds local agent worktrees (gitignored); they are
			// separate checkouts, not part of this tree.
			case ".git", "testdata", ".procoder", ".claude":
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		b, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if strings.HasPrefix(string(b), gen.HeaderPrefix) {
			return nil
		}
		head := string(b)
		if len(head) > 600 {
			head = head[:600]
		}
		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			return relErr
		}
		if !hasLicenseHeader(filepath.ToSlash(rel), head) {
			t.Errorf("%s: missing SPDX header", path)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
}
